// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@pythnetwork/entropy-sdk-solidity/IEntropy.sol";
import "@pythnetwork/entropy-sdk-solidity/IEntropyConsumer.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy private entropy;

    struct Game {
        address player;
        uint8 guess; // 0 = heads, 1 = tails
        uint256 betAmount;
        bool completed;
        bool won;
        uint8 result;
    }

    mapping(uint64 => Game) public games;
    mapping(address => uint256) public playerCoins;

    event GameCreated(uint64 indexed sequenceNumber, address indexed player, uint8 guess, uint256 betAmount);
    event GameResult(uint64 indexed sequenceNumber, address indexed player, uint8 result, bool won, uint256 payout);
    event CoinsReceived(address indexed player, uint256 amount);

    uint256 public constant INITIAL_COINS = 1000;

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
    }

    function getFreeCoins() external {
        require(playerCoins[msg.sender] == 0, "Already received free coins");
        playerCoins[msg.sender] = INITIAL_COINS;
        emit CoinsReceived(msg.sender, INITIAL_COINS);
    }

    function flipCoin(uint8 _guess, uint256 _betAmount) external payable returns (uint64) {
        require(_guess <= 1, "Invalid guess");
        require(_betAmount > 0, "Bet amount must be greater than 0");
        require(playerCoins[msg.sender] >= _betAmount, "Insufficient coins");

        // Deduct bet amount
        playerCoins[msg.sender] -= _betAmount;

        // Request randomness from Pyth Entropy
        bytes32 userRandomNumber = keccak256(abi.encodePacked(block.timestamp, msg.sender, _betAmount));
        uint256 fee = entropy.getFee(entropy.getDefaultProvider());
        require(msg.value >= fee, "Insufficient fee");

        uint64 sequenceNumber = entropy.requestWithCallback{value: fee}(
            entropy.getDefaultProvider(),
            userRandomNumber
        );

        games[sequenceNumber] = Game({
            player: msg.sender,
            guess: _guess,
            betAmount: _betAmount,
            completed: false,
            won: false,
            result: 0
        });

        emit GameCreated(sequenceNumber, msg.sender, _guess, _betAmount);
        return sequenceNumber;
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address,
        bytes32 randomNumber
    ) internal override {
        Game storage game = games[sequenceNumber];
        require(!game.completed, "Game already completed");

        // Convert random number to 0 or 1
        uint8 result = uint8(uint256(randomNumber) % 2);
        game.result = result;
        game.completed = true;

        // Check if player won
        if (game.guess == result) {
            game.won = true;
            uint256 payout = game.betAmount * 2;
            playerCoins[game.player] += payout;
            emit GameResult(sequenceNumber, game.player, result, true, payout);
        } else {
            emit GameResult(sequenceNumber, game.player, result, false, 0);
        }
    }

    function getGame(uint64 sequenceNumber) external view returns (Game memory) {
        return games[sequenceNumber];
    }

    function getPlayerCoins(address player) external view returns (uint256) {
        return playerCoins[player];
    }

    function getEntropyFee() external view returns (uint256) {
        return entropy.getFee(entropy.getDefaultProvider());
    }
}

import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import CoinFlip from './components/CoinFlip'
import './App.css'

// Contract address will be updated after deployment
const CONTRACT_ADDRESS = "0x..." // TODO: Update after deployment
const CONTRACT_ABI = [
  "function getFreeCoins() external",
  "function flipCoin(uint8 _guess, uint256 _betAmount) external payable returns (uint64)",
  "function getGame(uint64 sequenceNumber) external view returns (tuple(address player, uint8 guess, uint256 betAmount, bool completed, bool won, uint8 result))",
  "function getPlayerCoins(address player) external view returns (uint256)",
  "function getEntropyFee() external view returns (uint256)",
  "event GameCreated(uint64 indexed sequenceNumber, address indexed player, uint8 guess, uint256 betAmount)",
  "event GameResult(uint64 indexed sequenceNumber, address indexed player, uint8 result, bool won, uint256 payout)"
]

function App() {
  const [account, setAccount] = useState(null)
  const [contract, setContract] = useState(null)
  const [provider, setProvider] = useState(null)
  const [coins, setCoins] = useState(0)
  const [isConnecting, setIsConnecting] = useState(false)

  const connectWallet = async () => {
    if (!window.ethereum) {
      alert('Please install MetaMask!')
      return
    }

    try {
      setIsConnecting(true)

      // Request account access
      const accounts = await window.ethereum.request({
        method: 'eth_requestAccounts'
      })

      const provider = new ethers.BrowserProvider(window.ethereum)
      const signer = await provider.getSigner()
      const address = accounts[0]

      // Check if we're on Base Sepolia
      const network = await provider.getNetwork()
      if (network.chainId !== 84532n) {
        try {
          await window.ethereum.request({
            method: 'wallet_switchEthereumChain',
            params: [{ chainId: '0x14a34' }] // Base Sepolia
          })
        } catch (switchError) {
          // Add Base Sepolia if not added
          if (switchError.code === 4902) {
            await window.ethereum.request({
              method: 'wallet_addEthereumChain',
              params: [{
                chainId: '0x14a34',
                chainName: 'Base Sepolia',
                nativeCurrency: { name: 'ETH', symbol: 'ETH', decimals: 18 },
                rpcUrls: ['https://sepolia.base.org'],
                blockExplorerUrls: ['https://sepolia.basescan.org']
              }]
            })
          }
        }
      }

      setProvider(provider)
      setAccount(address)

      if (CONTRACT_ADDRESS !== "0x...") {
        const contractInstance = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, signer)
        setContract(contractInstance)

        // Get player's coin balance
        const balance = await contractInstance.getPlayerCoins(address)
        setCoins(Number(balance))
      }

    } catch (error) {
      console.error('Error connecting wallet:', error)
      alert('Failed to connect wallet')
    } finally {
      setIsConnecting(false)
    }
  }

  const getFreeCoins = async () => {
    if (!contract) return

    try {
      const tx = await contract.getFreeCoins()
      await tx.wait()

      // Update coin balance
      const balance = await contract.getPlayerCoins(account)
      setCoins(Number(balance))

      alert('Received 1000 free coins!')
    } catch (error) {
      console.error('Error getting free coins:', error)
      if (error.message.includes('Already received free coins')) {
        alert('You have already received your free coins!')
      } else {
        alert('Failed to get free coins')
      }
    }
  }

  return (
    <div className="App">
      <header className="App-header">
        <h1>🪙 Try - Coin Flip</h1>

        {!account ? (
          <div className="connect-section">
            <p>Connect your wallet to start playing!</p>
            <button 
              onClick={connectWallet} 
              disabled={isConnecting}
              className="connect-btn"
            >
              {isConnecting ? 'Connecting...' : 'Connect Wallet'}
            </button>
          </div>
        ) : (
          <div className="game-section">
            <div className="wallet-info">
              <p>Connected: {account.slice(0, 6)}...{account.slice(-4)}</p>
              <p>Coins: {coins}</p>
              {coins === 0 && (
                <button onClick={getFreeCoins} className="free-coins-btn">
                  Get Free Coins
                </button>
              )}
            </div>

            {CONTRACT_ADDRESS === "0x..." ? (
              <div className="deployment-notice">
                <p>🚧 Contract deployment in progress...</p>
                <p>Please wait while we deploy the smart contract to Base Sepolia</p>
              </div>
            ) : (
              <CoinFlip 
                contract={contract}
                account={account}
                coins={coins}
                setCoins={setCoins}
              />
            )}
          </div>
        )}
      </header>
    </div>
  )
}

export default App

import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import './CoinFlip.css'

const CoinFlip = ({ contract, account, coins, setCoins }) => {
  const [isFlipping, setIsFlipping] = useState(false)
  const [guess, setGuess] = useState(0) // 0 = heads, 1 = tails
  const [betAmount, setBetAmount] = useState(10)
  const [gameResult, setGameResult] = useState(null)
  const [currentSequence, setCurrentSequence] = useState(null)
  const [animationState, setAnimationState] = useState('idle') // idle, flipping, revealing

  useEffect(() => {
    if (!contract) return

    const handleGameResult = (sequenceNumber, player, result, won, payout) => {
      if (player.toLowerCase() === account.toLowerCase() && sequenceNumber === currentSequence) {
        console.log('Game result:', { sequenceNumber, result, won, payout })

        // Update coins
        setCoins(prevCoins => {
          const newCoins = won ? prevCoins + Number(payout) - betAmount : prevCoins
          return Math.max(0, newCoins)
        })

        // Show result after animation
        setTimeout(() => {
          setAnimationState('revealing')
          setGameResult({
            result: Number(result),
            won,
            payout: Number(payout)
          })

          setTimeout(() => {
            setIsFlipping(false)
            setAnimationState('idle')
            setCurrentSequence(null)
          }, 2000)
        }, 3000) // Wait for flip animation
      }
    }

    contract.on('GameResult', handleGameResult)

    return () => {
      contract.off('GameResult', handleGameResult)
    }
  }, [contract, account, currentSequence, betAmount, setCoins])

  const flipCoin = async () => {
    if (!contract || isFlipping) return

    if (betAmount <= 0) {
      alert('Please enter a valid bet amount')
      return
    }

    if (coins < betAmount) {
      alert('Insufficient coins!')
      return
    }

    try {
      setIsFlipping(true)
      setGameResult(null)
      setAnimationState('flipping')

      // Get the required fee
      const fee = await contract.getEntropyFee()

      // Make the flip
      const tx = await contract.flipCoin(guess, betAmount, { value: fee })
      const receipt = await tx.wait()

      // Extract sequence number from events
      const gameCreatedEvent = receipt.logs.find(log => {
        try {
          const parsed = contract.interface.parseLog(log)
          return parsed.name === 'GameCreated'
        } catch (e) {
          return false
        }
      })

      if (gameCreatedEvent) {
        const parsed = contract.interface.parseLog(gameCreatedEvent)
        setCurrentSequence(parsed.args.sequenceNumber)
      }

    } catch (error) {
      console.error('Error flipping coin:', error)
      setIsFlipping(false)
      setAnimationState('idle')

      if (error.message.includes('Insufficient fee')) {
        alert('Insufficient ETH for transaction fee')
      } else if (error.message.includes('user rejected')) {
        alert('Transaction cancelled')
      } else {
        alert('Failed to flip coin. Please try again.')
      }
    }
  }

  const getCoinSide = (value) => value === 0 ? 'HEADS' : 'TAILS'

  const getCoinEmoji = (value) => value === 0 ? '👑' : '⭐'

  return (
    <div className="coin-flip-game">
      <div className="game-controls">
        <div className="guess-section">
          <h3>Choose your guess:</h3>
          <div className="guess-buttons">
            <button 
              className={`guess-btn ${guess === 0 ? 'active' : ''}`}
              onClick={() => setGuess(0)}
              disabled={isFlipping}
            >
              👑 HEADS
            </button>
            <button 
              className={`guess-btn ${guess === 1 ? 'active' : ''}`}
              onClick={() => setGuess(1)}
              disabled={isFlipping}
            >
              ⭐ TAILS
            </button>
          </div>
        </div>

        <div className="bet-section">
          <label>Bet Amount:</label>
          <input 
            type="number" 
            value={betAmount}
            onChange={(e) => setBetAmount(Number(e.target.value))}
            min="1"
            max={coins}
            disabled={isFlipping}
          />
          <p className="bet-info">Win 2x your bet! ({betAmount} coins → {betAmount * 2} coins)</p>
        </div>

        <button 
          className="flip-btn"
          onClick={flipCoin}
          disabled={isFlipping || coins < betAmount}
        >
          {isFlipping ? 'Flipping...' : 'Flip Coin!'}
        </button>
      </div>

      <div className="coin-container">
        <div className={`coin ${animationState}`}>
          {animationState === 'revealing' && gameResult ? (
            <div className="coin-face final">
              {getCoinEmoji(gameResult.result)}
            </div>
          ) : (
            <>
              <div className="coin-face heads">👑</div>
              <div className="coin-face tails">⭐</div>
            </>
          )}
        </div>

        {animationState === 'flipping' && (
          <p className="flip-text">The coin is spinning...</p>
        )}
      </div>

      {gameResult && animationState === 'revealing' && (
        <div className={`result ${gameResult.won ? 'win' : 'lose'}`}>
          <h3>{gameResult.won ? '🎉 You Won!' : '😔 You Lost!'}</h3>
          <p>Result: {getCoinEmoji(gameResult.result)} {getCoinSide(gameResult.result)}</p>
          <p>Your guess: {getCoinEmoji(guess)} {getCoinSide(guess)}</p>
          {gameResult.won && (
            <p>You won {gameResult.payout} coins!</p>
          )}
        </div>
      )}
    </div>
  )
}

export default CoinFlip

.coin-flip-game {
  max-width: 500px;
  margin: 0 auto;
  padding: 20px;
}

.game-controls {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 15px;
  padding: 20px;
  margin-bottom: 30px;
  backdrop-filter: blur(10px);
}

.guess-section {
  margin-bottom: 20px;
}

.guess-section h3 {
  margin-bottom: 15px;
  color: #fff;
  text-align: center;
}

.guess-buttons {
  display: flex;
  gap: 15px;
  justify-content: center;
}

.guess-btn {
  padding: 15px 25px;
  border: 2px solid #4CAF50;
  background: rgba(76, 175, 80, 0.2);
  color: white;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 16px;
  font-weight: bold;
}

.guess-btn:hover {
  background: rgba(76, 175, 80, 0.4);
  transform: translateY(-2px);
}

.guess-btn.active {
  background: #4CAF50;
  box-shadow: 0 0 20px rgba(76, 175, 80, 0.6);
}

.guess-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.bet-section {
  margin-bottom: 20px;
  text-align: center;
}

.bet-section label {
  display: block;
  margin-bottom: 10px;
  color: #fff;
  font-weight: bold;
}

.bet-section input {
  padding: 10px;
  border: 2px solid #ddd;
  border-radius: 8px;
  width: 150px;
  text-align: center;
  font-size: 16px;
}

.bet-info {
  color: #ccc;
  margin-top: 10px;
  font-size: 14px;
}

.flip-btn {
  width: 100%;
  padding: 15px;
  background: linear-gradient(45deg, #FF6B6B, #4ECDC4);
  border: none;
  border-radius: 10px;
  color: white;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s ease;
}

.flip-btn:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
}

.flip-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.coin-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 40px 0;
}

.coin {
  width: 120px;
  height: 120px;
  position: relative;
  margin-bottom: 20px;
}

.coin-face {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  border-radius: 50%;
  position: absolute;
  top: 0;
  left: 0;
  border: 4px solid #FFD700;
  background: linear-gradient(45deg, #FFD700, #FFA500);
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
}

.coin-face.heads {
  transform: rotateY(0deg);
}

.coin-face.tails {
  transform: rotateY(180deg);
}

.coin.idle .coin-face {
  transition: transform 0.3s ease;
}

.coin.flipping {
  animation: coinFlip 3s ease-in-out;
}

.coin.revealing .coin-face.final {
  animation: coinReveal 1s ease-out;
}

@keyframes coinFlip {
  0% {
    transform: rotateY(0deg) rotateX(0deg);
  }
  25% {
    transform: rotateY(450deg) rotateX(180deg) scale(1.1);
  }
  50% {
    transform: rotateY(900deg) rotateX(360deg) scale(1.2);
  }
  75% {
    transform: rotateY(1350deg) rotateX(540deg) scale(1.1);
  }
  100% {
    transform: rotateY(1800deg) rotateX(720deg) scale(1);
  }
}

@keyframes coinReveal {
  0% {
    transform: scale(1);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.3);
    opacity: 1;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

.flip-text {
  color: #fff;
  font-style: italic;
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 0.6;
  }
  50% {
    opacity: 1;
  }
}

.result {
  text-align: center;
  padding: 20px;
  border-radius: 15px;
  margin-top: 20px;
  animation: resultSlideIn 0.5s ease-out;
}

.result.win {
  background: rgba(76, 175, 80, 0.2);
  border: 2px solid #4CAF50;
  color: #4CAF50;
}

.result.lose {
  background: rgba(244, 67, 54, 0.2);
  border: 2px solid #F44336;
  color: #F44336;
}

.result h3 {
  margin-bottom: 15px;
  font-size: 24px;
}

.result p {
  margin: 5px 0;
  font-size: 16px;
}

@keyframes resultSlideIn {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

